select
  (select count(*) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'initialize_studio_payment_jurisdiction_from_history_v2') as v2_count,
  (select p.prosecdef from pg_catalog.pg_proc p where p.oid = pg_catalog.to_regprocedure('public.initialize_studio_payment_jurisdiction_from_history_v2(pg_catalog.uuid,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.bool,pg_catalog.text[],pg_catalog.uuid[],pg_catalog.uuid[],pg_catalog.text)')) as v2_secdef,
  (select array_to_string(p.proconfig, ',') from pg_catalog.pg_proc p where p.oid = pg_catalog.to_regprocedure('public.initialize_studio_payment_jurisdiction_from_history_v2(pg_catalog.uuid,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.bool,pg_catalog.text[],pg_catalog.uuid[],pg_catalog.uuid[],pg_catalog.text)')) as v2_config,
  (select p.proacl::text from pg_catalog.pg_proc p where p.oid = pg_catalog.to_regprocedure('public.initialize_studio_payment_jurisdiction_from_history_v2(pg_catalog.uuid,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.text,pg_catalog.bool,pg_catalog.text[],pg_catalog.uuid[],pg_catalog.uuid[],pg_catalog.text)')) as v2_acl,
  (select string_agg(a.attname || ':' || pg_catalog.format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text || ':' || coalesce(pg_catalog.pg_get_expr(d.adbin, d.adrelid), '-'), ';' order by a.attname)
     from pg_catalog.pg_attribute a left join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
    where a.attrelid = 'public.studio_payment_jurisdiction_changes'::pg_catalog.regclass and a.attname in ('failed_attempts_acknowledged', 'failed_attempts_evidence') and not a.attisdropped) as columns_text,
  (select pg_catalog.pg_get_constraintdef(c.oid) from pg_catalog.pg_constraint c where c.conrelid = 'public.studio_payment_jurisdiction_changes'::pg_catalog.regclass and c.conname = 'studio_payment_jurisdiction_changes_failed_evidence_check') as check_def,
  (select c.convalidated from pg_catalog.pg_constraint c where c.conrelid = 'public.studio_payment_jurisdiction_changes'::pg_catalog.regclass and c.conname = 'studio_payment_jurisdiction_changes_failed_evidence_check') as check_validated,
  (select count(*) from public.studio_payment_jurisdiction_changes where cardinality(failed_attempts_acknowledged) > 0) as rows_with_acknowledgement
